151		// Raw textual pinning: the exact tokens must survive, in their original
152		// object/array positions and adjacency, without re-notation.
153		requireContains(t, lines[0],
154			`"nested":{"big":9007199254740993,"dec":1.0000000000000000001,"huge":1e400,"tiny":1e-400,`+
155				`"arr":[9007199254740993,1.0000000000000000001,1e400,1e-400,"9007199254740993","1e400",true,false,null]}`)
156		requireContains(t, lines[0], `"extra":{"own":9007199254740993,"label":"kept"}`)
157		requireContains(t, lines[1],
158			`"extra":{"asString":"1.0000000000000000001","big":9007199254740993,`+
159				`"dec":1.0000000000000000001,"flag":true,"huge":1e400,"missing":null,"tiny":1e-400}`)
160	
161		// The specific corruptions float-style re-serialization would introduce
162		// must never appear anywhere in the output.
163		for _, banned := range []string{
164			"9007199254740992", // the rounded neighbor float64 would produce
165			"1e+400",           // Go's float64 notation
166			"Infinity",
167			"Inf",
168		} {
169			if strings.Contains(result.stdout, banned) {
170				t.Fatalf("output must not rewrite extension numbers into %q:\n%s", banned, result.stdout)
171			}
172		}
173	
174		// Type-level pinning, whitespace-insensitive: numbers decode as json.Number
175		// carrying the exact literal; string-written numbers decode as strings.
176		n1 := decodeResultWithNumbers(t, lines[0])
177		ev1 := n1["event"].(map[string]any)
178		extra1 := ev1["extra"].(map[string]any)
179	
180		ownExtra, ok := extra1["extra"].(map[string]any)
181		if !ok {
182			t.Fatalf("the input's own extra must nest under output extra, not merge: %#v", extra1)
183		}
184		if got := ownExtra["own"]; got != json.Number("9007199254740993") {
185			t.Fatalf("number inside input-owned extra must keep type and spelling, got %#v", got)
186		}
187		if got := ownExtra["label"]; got != "kept" {
188			t.Fatalf("string sibling inside input-owned extra must survive, got %#v", got)
189		}
190		if _, merged := extra1["own"]; merged {
191			t.Fatalf("input-owned extra members must not be hoisted into the output extra: %#v", extra1)
192		}
193	
194		nested, ok := extra1["nested"].(map[string]any)
195		if !ok {
196			t.Fatalf("nested unknown object must survive: %#v", extra1["nested"])
197		}
198		wantNested := map[string]json.Number{
199			"big":  "9007199254740993",
200			"dec":  "1.0000000000000000001",
201			"huge": "1e400",
202			"tiny": "1e-400",
203		}
204		for key, want := range wantNested {
205			if got, ok := nested[key].(json.Number); !ok || string(got) != string(want) {
206				t.Fatalf("nested %s must be JSON number %s, got %#v", key, want, nested[key])
207			}
208		}
209		arr, ok := nested["arr"].([]any)
210		if !ok || len(arr) != 9 {
211			t.Fatalf("nested array must keep all nine elements in order, got %#v", nested["arr"])
212		}
213		wantArr := []struct {
214			check func(any) bool
215			label string
216		}{
217			{isNumber("9007199254740993"), "number 9007199254740993"},
218			{isNumber("1.0000000000000000001"), "number 1.0000000000000000001"},
219			{isNumber("1e400"), "number 1e400"},
220			{isNumber("1e-400"), "number 1e-400"},
221			{isString("9007199254740993"), "string \"9007199254740993\""},
222			{isString("1e400"), "string \"1e400\""},
223			{isBool(true), "boolean true"},
224			{isBool(false), "boolean false"},
225			{isNull(), "null"},
226		}
227		for i, w := range wantArr {
228			if !w.check(arr[i]) {
229				t.Fatalf("array element %d must be %s, got %#v (array: %#v)", i, w.label, arr[i], arr)
230			}
231		}
232	
233		n2 := decodeResultWithNumbers(t, lines[1])
234		extra2 := n2["event"].(map[string]any)["extra"].(map[string]any)
235		for key, want := range map[string]json.Number{
236			"big":  "9007199254740993",
237			"dec":  "1.0000000000000000001",
238			"huge": "1e400",
239			"tiny": "1e-400",
240		} {
241			if got, ok := extra2[key].(json.Number); !ok || string(got) != string(want) {
242				t.Fatalf("top-level extra %s must be JSON number %s, got %#v", key, want, extra2[key])
243			}
244		}
245		if got, ok := extra2["asString"].(string); !ok || got != "1.0000000000000000001" {
246			t.Fatalf("a string-written number must remain a distinct string, got %#v", extra2["asString"])
247		}
248		if extra2["flag"] != true {
249			t.Fatalf("boolean sibling must survive, got %#v", extra2["flag"])
250		}
251		if _, present := extra2["missing"]; !present || extra2["missing"] != nil {
252			t.Fatalf("null sibling must survive as null, got %#v", extra2["missing"])
253		}
254	}
255	
256	func isNumber(want string) func(any) bool {
257		return func(v any) bool {
258			n, ok := v.(json.Number)
259			return ok && string(n) == want
260		}
261	}
262	func isString(want string) func(any) bool {
263		return func(v any) bool {
264			s, ok := v.(string)
265			return ok && s == want
266		}
267	}
268	func isBool(want bool) func(any) bool {
269		return func(v any) bool {
270			b, ok := v.(bool)
271			return ok && b == want
272		}
273	}
274	func isNull() func(any) bool {
275		return func(v any) bool { return v == nil }
276	}
277	
278	// A number given directly to a mapped field is a type error regardless of
279	// whether the canonical name or its alias carries it: the line fails with the
280	// canonical field's "must be a string, got number" reason, carries no event,
281	// and the run exits 1. This holds even when the number is a big integer or an
282	// extreme exponent that extra would otherwise preserve — extension-number
283	// retention never loosens the standard-field contract.
284	func TestNormalizeCLINumberInStandardFieldFails(t *testing.T) {
285		const ts = `"2026-01-02T00:00:00Z"`
286		cases := []struct {
287			name      string
288			line      string
289			canonical string
290		}{
291			{"timestamp canonical", `{"timestamp":1700000000,"action":"a"}`, "timestamp"},
292			{"timestamp alias big integer", `{"time":9007199254740993,"action":"a"}`, "timestamp"},
293			{"source_ip canonical", `{"timestamp":` + ts + `,"action":"a","source_ip":12345}`, "source_ip"},
294			{"source_ip alias exponent", `{"timestamp":` + ts + `,"action":"a","src_ip":1e400}`, "source_ip"},
295			{"action canonical integer", `{"timestamp":` + ts + `,"action":42}`, "action"},
296			{"action alias decimal", `{"timestamp":` + ts + `,"event_type":1.5}`, "action"},
297		}
298		for _, tc := range cases {
299			t.Run(tc.name, func(t *testing.T) {
300				result := runNormalizeCLI(t, strings.NewReader(tc.line+"\n"))
301				if result.exitCode != 1 {
302					t.Fatalf("a numeric standard field must exit 1, got %d (stderr: %q)", result.exitCode, result.stderr)
303				}
304				if result.stderr != "" {
305					t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
306				}
307				records := decodeStdoutResults(t, result.stdout)
308				if len(records) != 1 {
309					t.Fatalf("expected exactly one failure record, got %#v", records)
310				}
311				r := records[0]
312				if r["line"] != float64(1) || r["ok"] != false {
313					t.Fatalf("the bad line must be line 1 ok=false: %#v", r)
314				}
315				if _, exists := r["event"]; exists {
316					t.Fatalf("a type-invalid line must carry no event: %#v", r)
317				}
318				if len(r) != 3 {
319					t.Fatalf("a failure record carries exactly line, ok and error, got %#v", r)
320				}
321				want := `field "` + tc.canonical + `": value must be a string, got number`
322				if r["error"] != want {
323					t.Fatalf("error must name canonical field %q and demand a string, got %q", tc.canonical, r["error"])
324				}
325			})
326		}
327	}
328	
329	// Extension numbers must be legal JSON number tokens to be preserved. Leading
330	// zeros (01) and bare NaN are JSON syntax errors, not valid values to store:
331	// the line fails as invalid JSON with no event. In the same batch, a legal
332	// evidence line, a number-into-standard-field line, a blank physical line,
333	// these two syntax failures, and a trailing legal evidence line must all be
334	// reported in input order with the blank only consuming a line number; the
335	// trailing valid line still succeeds, stderr stays empty and the run exits 1.
336	func TestNormalizeCLIIllegalJSONNumbersAndMixedBatch(t *testing.T) {
337		input := bytes.Join([][]byte{
338			[]byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"a","big":9007199254740993}`), // 1: ok
339			[]byte(`{"timestamp":1700000000,"action":"a"}`),                                    // 2: fail (number field)
340			[]byte(``), // 3: blank, no record
341			[]byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"a","bad":01}`),      // 4: fail (invalid JSON)
342			[]byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"a","bad":NaN}`),     // 5: fail (invalid JSON)
343			[]byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"z","tiny":1e-400}`), // 6: ok
344		}, []byte("\n"))
345	
346		result := runNormalizeCLI(t, bytes.NewReader(input))
347	
348		if result.exitCode != 1 {
349			t.Fatalf("a batch containing failed logs must exit 1, got %d (stderr: %q)", result.exitCode, result.stderr)
350		}
351		if result.stderr != "" {
352			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
353		}
354	
355		records := decodeStdoutResults(t, result.stdout)
356		if len(records) != 5 {
357			t.Fatalf("the blank line produces no record; expected 5, got %#v", records)
358		}
359	
360		want := []struct {
361			line float64
362			ok   bool
363		}{
364			{1, true},
365			{2, false},
366			{4, false},
367			{5, false},
368			{6, true},
369		}
370		for i, w := range want {
371			if records[i]["line"] != w.line || records[i]["ok"] != w.ok {
372				t.Fatalf("record %d must be physical line %v ok=%v, got %#v", i, w.line, w.ok, records[i])
373			}
374		}
375	
376		if eventOf(t, records[0])["action"] != "a" {
377			t.Fatalf("line 1 event mismatch: %#v", records[0])
378		}
379		if eventOf(t, records[4])["action"] != "z" {
380			t.Fatalf("the trailing legal log must still normalize after failures: %#v", records[4])
381		}
382	
383		// Failures carry only physical line number, ok:false and a reason.
384		for _, i := range []int{1, 2, 3} {
385			r := records[i]
386			if _, exists := r["event"]; exists {
387				t.Fatalf("failed line %v must carry no event: %#v", r["line"], r)
388			}
389			if len(r) != 3 {
390				t.Fatalf("failed line %v must carry exactly line, ok and error: %#v", r["line"], r)
391			}
392		}
393		if got := records[1]["error"]; got != `field "timestamp": value must be a string, got number` {
394			t.Fatalf("line 2 must report the numeric timestamp, got %q", got)
395		}
396		for _, i := range []int{2, 3} {
397			msg, _ := records[i]["error"].(string)
398			if !strings.Contains(msg, "invalid JSON") {
399				t.Fatalf("line %v must fail as invalid JSON, not be stored as a number; got %q", records[i]["line"], msg)
400			}
401		}
402	
403		// Evidence on the legal lines is intact, in raw text.
404		lines := rawResultLines(t, result.stdout)
405		requireContains(t, lines[0], `"big":9007199254740993`)
406		requireContains(t, lines[4], `"tiny":1e-400`)
407	}
